sys_script.script:
try {
    // 检查审批状态是否发生变化
    if (current.approval.changesTo('approved') || current.approval.changesTo('rejected')) {

        var applicant = current.opened_by.getRefRecord();
        var applicantSysId = current.opened_by.toString();
        var leaveNumber = current.number.toString();
        var applicantName = applicant ? applicant.getDisplayValue() : 'Unknown';
        var leaveReason = current.short_description.toString();
        var approvalStatus = current.approval.toString();
        var currentTime = new GlideDateTime().getDisplayValue();

        if (applicantSysId) {
            var workNotesMessage = '';

            if (approvalStatus === 'approved') {
                workNotesMessage = '🎉 【系统通知】请假申请已获得批准！\n' +
                                 '申请人：' + applicantName + '\n' +
                                 '审批时间：' + currentTime + '\n' +
                                 '通知方式：邮件通知已发送\n' +
                                 '建议：请查看邮件了解详细的请假须知和注意事项。';
            } else if (approvalStatus === 'rejected') {
                workNotesMessage = '❌ 【系统通知】请假申请已被驳回\n' +
                                 '申请人：' + applicantName + '\n' +
                                 '驳回时间：' + currentTime + '\n' +
                                 '通知方式：邮件通知已发送\n' +
                                 '建议：请查看邮件了解驳回原因和后续步骤。';
            }

            if (workNotesMessage) {
                // 更新Work Notes - 这是记录自己的字段，不涉及跨范围访问
                if (current.work_notes && current.work_notes.toString().length > 0) {
                    current.work_notes = current.work_notes.toString() + '\n\n' + workNotesMessage;
                } else {
                    current.work_notes = workNotesMessage;
                }

                gs.info('✅ Work Notes通知已添加');
                gs.info('申请编号: ' + leaveNumber);
                gs.info('申请人: ' + applicantName + ' (' + applicantSysId + ')');
                gs.info('审批状态: ' + approvalStatus);
                gs.info('Work Notes内容: ' + workNotesMessage);

                // 存储到系统属性以便UI显示
                try {
                    var timestamp = new GlideDateTime().getNumericValue();
                    var propertyName = 'x_1973840_leave.latest_notification.' + applicantSysId;
                    var notificationData = {
                        message: (approvalStatus === 'approved') ? 
                                ('🎉 您的请假申请 ' + leaveNumber + ' 已获得批准！') :
                                ('❌ 很抱歉，您的请假申请 ' + leaveNumber + ' 已被驳回。'),
                        type: (approvalStatus === 'approved') ? 'success' : 'error',
                        timestamp: timestamp,
                        leave_number: leaveNumber,
                        applicant_name: applicantName,
                        approval_status: approvalStatus,
                        display_time: currentTime,
                        show_banner: true
                    };

                    gs.setProperty(propertyName, JSON.stringify(notificationData));
                    gs.info('✅ 用户通知属性已保存: ' + propertyName);

                } catch (propertyError) {
                    gs.warn('保存通知属性失败: ' + propertyError.message);
                }
            }
        }
    }
} catch (globalError) {
    gs.error('Work Notes通知业务规则执行出错: ' + globalError.message);
}
